        if (tile(tx, ty + 1) === T.WATER) for (let k = 0; k < TP; k += 4) { x.fillStyle = (k / 4 + tx) % 2 ? '#e0b83a' : '#1b1b1f'; x.fillRect(px + k, py + TP - 3, 4, 3); }
