        for (let k = 0; k < 6; k++) { const o = -TS / 2 + .17 + k * .33; const b = cyl(.05, .07, .8, 5, balM); b.position.set(along ? cx + o : ex, top + .5, along ? ez : cz + o); put(b, 'bal'); }
