        [-1, 1].forEach(sg => { const a = ga + sg * .35, x = C.x + Math.cos(a) * (C.r - 2), z = C.y + Math.sin(a) * (C.r - 2); sacchi(x, z, -a + Math.PI / 2, 4); });
