    [T0 + TH * .45].forEach(y => deck(y, 2.6, false)); add(g, cyl(2.3, 2.3, .5, 14, steel), 0, T0 + TH * .45 - .2, 0);
    // scala alla marinara sul fianco e scala dalla piattaforma
