      const top0 = tvTop(a0, W0.tavR(a0) - 4.5) + .25, top1 = tvTop(a1, W0.tavR(a1) - 4.5) + .25, bot0 = botAt(a0, R0, top0), bot1 = botAt(a1, R1, top1);
