      const X = wx + (si + .5) * .25, Y = wy + (sj + .5) * .25, pc = vdParcel(X, Y), u = vdCampoUV(pc, X, Y)[0], n1 = vnz(X / 4 + pc.a * 3, Y / 4 + pc.b * 3);
