        const ca = a.ux * b.ux + a.uy * b.uy, sinH = Math.sqrt(Math.max(.08, (1 - ca) / 2)), dd = (Math.max(a.w, b.w) / 2 + .7) / sinH, cx = jx + bx * dd, cz = jy + by * dd;
