      blade.position.set(px, base + 4 + hh / 2, pz); blade.rotation.y = face === 'E' || face === 'W' ? Math.PI / 2 : 0;
      scene.add(blade); p2Obj(blade, 'insegna', b, face);   // [pulizia2]
