      const at = (m, x, y, z) => { m.position.set(x, y0 + y, z); g.add(m); return m; };
      at(box(w - .4, .3, d - .4, sm('#9a948a')), cx, .15, cz);                        // zoccolo
      at(box(w - .6, H, d - .6, white), cx, .3 + H / 2, cz);                          // il chiosco
