    if (ex.includes('belt')) { const bl = box(.52 * s, .07, .32, M('#e8e8e8')); bl.position.y = hipY + .04; body.add(bl); }
    if (ex.includes('gold')) { const gd = box(.14, .04, .02, M('#e8c040')); gd.position.set(0, hipY + .5, .16); body.add(gd); }
