    const cloth = ['#d8d0b8', '#b04a4a', '#4a6aa0', '#caa83a'].map(c => animMat(std({ color: c, roughness: 1 }), 'giu:panno:1.4'));   // [animazioni-mondo] il bucato sui tetti sventola
