    for (let k = 0; k < 3; k++) { const bl = fB(.36, .05, .012, '#5a5a5e', 'solid', .004); bl.position.set(fx, y0 + H / 2, D / 2 - .02); bl.rotation.z = k * 1.05 + r(); g.add(bl); }   // pale
