      if (R.t > 2.6) { R.rig.visible = false; return; }
      const t = (R.t += dt), a = t < .4 ? Math.sin(t / .4 * Math.PI / 2) * 1.3 : t < 1.6 ? 1.3 : t < 2.3 ? 1.3 * Math.cos((t - 1.6) / .7 * Math.PI / 2) : 0;
